"use client"

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type FormEvent,
  type PointerEvent as ReactPointerEvent,
} from "react"
import {
  ArrowDownToLine,
  Check,
  ChevronDown,
  CircleDot,
  Copy,
  Download,
  Frame,
  Hand,
  Maximize2,
  Minus,
  MousePointer2,
  Network,
  Plus,
  Redo2,
  RotateCcw,
  Scan,
  Share2,
  Sparkles,
  Square,
  Trash2,
  Type,
  Undo2,
  Waypoints,
  X,
} from "lucide-react"

import {
  Diagram,
  DiagramFrame,
  DiagramProvider,
  type DiagramViewport,
} from "@/components/draft/diagram"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import {
  ToggleGroup,
  ToggleGroupItem,
} from "@/components/ui/toggle-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  createInitialDocument,
  DRAFT_CANVAS_HEIGHT,
  DRAFT_CANVAS_WIDTH,
  DRAFT_GRID_SIZE,
  DRAFT_NODE_HEIGHT,
  DRAFT_NODE_WIDTH,
  DRAFT_TONE_COLORS,
  normalizeDraftDocument,
  parseDraftDocument,
  prepareDraftDocument,
  snapToDraftGrid,
  type DraftDocument,
  type DraftNode,
  type DraftNodeData,
  type DraftNodeKind,
  type DraftPoint,
  type DraftTone,
} from "@/lib/draft-document"
import { cn } from "@/lib/utils"

import styles from "./diagram-editor.module.css"

const STORAGE_KEY = "draft:edge-request-path:v2"

const toolItems = [
  { id: "select", label: "Select", icon: MousePointer2, key: "V" },
  { id: "hand", label: "Pan canvas", icon: Hand, key: "H" },
  { id: "node", label: "Add node", icon: Square, key: "N" },
  { id: "text", label: "Add annotation", icon: Type, key: "T" },
  { id: "connect", label: "Connect", icon: Waypoints, key: "C" },
] as const

type ToolId = (typeof toolItems)[number]["id"]

type NodeDrag = {
  pointerId: number
  nodeId: string
  pointerOrigin: DraftPoint
  nodeOrigin: DraftPoint
}

type ViewportDrag = {
  pointerId: number
  clientX: number
  clientY: number
  viewport: DiagramViewport
}

function getCanvasPoint(
  event: ReactPointerEvent<SVGElement>,
  svg: SVGSVGElement
) {
  const matrix = svg.getScreenCTM()
  if (!matrix) return null

  return new DOMPoint(event.clientX, event.clientY).matrixTransform(
    matrix.inverse()
  )
}

function ToolButton({
  item,
  active,
  onClick,
}: {
  item: (typeof toolItems)[number]
  active: boolean
  onClick: () => void
}) {
  const Icon = item.icon

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          aria-label={item.label}
          aria-pressed={active}
          variant="ghost"
          size="icon"
          className={cn(styles.toolButton, active && styles.toolButtonActive)}
          onClick={onClick}
        >
          <Icon aria-hidden="true" />
        </Button>
      </TooltipTrigger>
      <TooltipContent side="right" sideOffset={8}>
        <span>{item.label}</span>
        <kbd>{item.key}</kbd>
      </TooltipContent>
    </Tooltip>
  )
}

function DiagramEditorOverlay({
  document,
  activeTool,
  selectedNodeId,
  connectionSourceId,
  viewport,
  onSelectNode,
  onMoveNode,
  onConnectNode,
  onChangeViewport,
}: {
  document: DraftDocument
  activeTool: ToolId
  selectedNodeId: string | null
  connectionSourceId: string | null
  viewport: DiagramViewport
  onSelectNode: (nodeId: string | null) => void
  onMoveNode: (nodeId: string, position: DraftPoint) => void
  onConnectNode: (nodeId: string) => void
  onChangeViewport: (viewport: DiagramViewport) => void
}) {
  const nodeDrag = useRef<NodeDrag | null>(null)
  const viewportDrag = useRef<ViewportDrag | null>(null)
  const nodes = document.graph.nodes.filter(
    (node): node is DraftNode => node.type === "node"
  )
  const selectedNode =
    nodes.find((node) => node.id === selectedNodeId) ?? null

  const handleNodePointerDown = (
    event: ReactPointerEvent<SVGRectElement>,
    node: DraftNode
  ) => {
    event.preventDefault()
    event.stopPropagation()
    onSelectNode(node.id)

    if (activeTool === "connect") {
      onConnectNode(node.id)
      return
    }
    if (activeTool !== "select") return

    const svg = event.currentTarget.ownerSVGElement
    if (!svg) return
    const point = getCanvasPoint(event, svg)
    if (!point) return

    event.currentTarget.setPointerCapture(event.pointerId)
    nodeDrag.current = {
      pointerId: event.pointerId,
      nodeId: node.id,
      pointerOrigin: { x: point.x, y: point.y },
      nodeOrigin: node.position,
    }
  }

  const handleNodePointerMove = (
    event: ReactPointerEvent<SVGRectElement>
  ) => {
    const drag = nodeDrag.current
    if (!drag || drag.pointerId !== event.pointerId) return

    const svg = event.currentTarget.ownerSVGElement
    if (!svg) return
    const point = getCanvasPoint(event, svg)
    if (!point) return

    onMoveNode(drag.nodeId, {
      x: drag.nodeOrigin.x + point.x - drag.pointerOrigin.x,
      y: drag.nodeOrigin.y + point.y - drag.pointerOrigin.y,
    })
  }

  const finishNodeDrag = (event: ReactPointerEvent<SVGRectElement>) => {
    if (nodeDrag.current?.pointerId !== event.pointerId) return
    nodeDrag.current = null
    event.currentTarget.releasePointerCapture(event.pointerId)
  }

  const handlePanePointerDown = (
    event: ReactPointerEvent<SVGRectElement>
  ) => {
    if (activeTool === "select") {
      onSelectNode(null)
      return
    }
    if (activeTool !== "hand") return

    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    viewportDrag.current = {
      pointerId: event.pointerId,
      clientX: event.clientX,
      clientY: event.clientY,
      viewport,
    }
  }

  const handlePanePointerMove = (
    event: ReactPointerEvent<SVGRectElement>
  ) => {
    const drag = viewportDrag.current
    if (!drag || drag.pointerId !== event.pointerId) return

    const svg = event.currentTarget.ownerSVGElement
    if (!svg) return
    const bounds = svg.getBoundingClientRect()
    const scaleX = drag.viewport.width / bounds.width
    const scaleY = drag.viewport.height / bounds.height

    onChangeViewport({
      ...drag.viewport,
      x: drag.viewport.x - (event.clientX - drag.clientX) * scaleX,
      y: drag.viewport.y - (event.clientY - drag.clientY) * scaleY,
    })
  }

  const finishViewportDrag = (event: ReactPointerEvent<SVGRectElement>) => {
    if (viewportDrag.current?.pointerId !== event.pointerId) return
    viewportDrag.current = null
    event.currentTarget.releasePointerCapture(event.pointerId)
  }

  return (
    <g data-draft-editor-overlay="">
      <rect
        x={viewport.x}
        y={viewport.y}
        width={viewport.width}
        height={viewport.height}
        fill="transparent"
        className={activeTool === "hand" ? styles.pannablePane : undefined}
        onPointerDown={handlePanePointerDown}
        onPointerMove={handlePanePointerMove}
        onPointerUp={finishViewportDrag}
        onPointerCancel={finishViewportDrag}
      />

      {selectedNode ? (
        <g pointerEvents="none">
          <rect
            x={selectedNode.position.x - 4}
            y={selectedNode.position.y - 4}
            width={selectedNode.size.width + 8}
            height={selectedNode.size.height + 8}
            rx={6}
            className={styles.selectionBox}
          />
          {(["top", "right", "bottom", "left"] as const).map((port) => {
            const position =
              port === "top"
                ? {
                    x: selectedNode.position.x + selectedNode.size.width / 2,
                    y: selectedNode.position.y,
                  }
                : port === "right"
                  ? {
                      x: selectedNode.position.x + selectedNode.size.width,
                      y: selectedNode.position.y + selectedNode.size.height / 2,
                    }
                  : port === "bottom"
                    ? {
                        x: selectedNode.position.x + selectedNode.size.width / 2,
                        y: selectedNode.position.y + selectedNode.size.height,
                      }
                    : {
                        x: selectedNode.position.x,
                        y: selectedNode.position.y + selectedNode.size.height / 2,
                      }

            return (
              <circle
                key={port}
                cx={position.x}
                cy={position.y}
                r={4}
                className={styles.selectionPort}
              />
            )
          })}
        </g>
      ) : null}

      {nodes.map((node) => (
        <rect
          key={node.id}
          data-editor-node={node.id}
          x={node.position.x}
          y={node.position.y}
          width={node.size.width}
          height={node.size.height}
          fill="transparent"
          className={cn(
            styles.nodeHitArea,
            activeTool === "connect" && styles.nodeConnectArea,
            connectionSourceId === node.id && styles.connectionSource
          )}
          onPointerDown={(event) => handleNodePointerDown(event, node)}
          onPointerMove={handleNodePointerMove}
          onPointerUp={finishNodeDrag}
          onPointerCancel={finishNodeDrag}
        />
      ))}
    </g>
  )
}

export function DiagramEditor() {
  const [diagramDocument, setDiagramDocument] =
    useState<DraftDocument>(createInitialDocument)
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(
    "edge-proxy"
  )
  const [connectionSourceId, setConnectionSourceId] = useState<string | null>(
    null
  )
  const [activeTool, setActiveTool] = useState<ToolId>("select")
  const [viewport, setViewport] = useState<DiagramViewport>(() => ({
    x: 0,
    y: 0,
    width: DRAFT_CANVAS_WIDTH,
    height: DRAFT_CANVAS_HEIGHT,
  }))
  const [command, setCommand] = useState("")
  const [presenting, setPresenting] = useState(false)
  const [hydrated, setHydrated] = useState(false)
  const [notice, setNotice] = useState<string | null>(null)

  const nodes = diagramDocument.graph.nodes
  const edges = diagramDocument.graph.edges
  const selectedNode = useMemo(
    () =>
      nodes.find(
        (node): node is DraftNode =>
          node.id === selectedNodeId && node.type === "node"
      ) ?? null,
    [nodes, selectedNodeId]
  )

  const showNotice = useCallback((message: string) => {
    setNotice(message)
    window.setTimeout(() => setNotice(null), 2200)
  }, [])

  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      try {
        const saved = window.localStorage.getItem(STORAGE_KEY)
        if (saved) {
          const parsed = parseDraftDocument(JSON.parse(saved))
          if (parsed) setDiagramDocument(parsed)
        }
      } catch {
        window.localStorage.removeItem(STORAGE_KEY)
      } finally {
        setHydrated(true)
      }
    })

    return () => window.cancelAnimationFrame(frame)
  }, [])

  useEffect(() => {
    if (!hydrated) return
    const timeout = window.setTimeout(() => {
      window.localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify(prepareDraftDocument(diagramDocument))
      )
    }, 300)
    return () => window.clearTimeout(timeout)
  }, [diagramDocument, hydrated])

  const deleteSelectedNode = useCallback(() => {
    if (!selectedNodeId) return

    setDiagramDocument((current) => ({
      ...current,
      graph: {
        nodes: current.graph.nodes.filter(
          (node) => node.id !== selectedNodeId
        ),
        edges: current.graph.edges.filter(
          (edge) =>
            edge.source !== selectedNodeId && edge.target !== selectedNodeId
        ),
      },
    }))
    setSelectedNodeId(null)
  }, [selectedNodeId])

  useEffect(() => {
    const handleKey = (event: KeyboardEvent) => {
      if (
        event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      const tool = toolItems.find(
        (item) => item.key.toLowerCase() === event.key.toLowerCase()
      )
      if (tool) {
        setActiveTool(tool.id)
        setConnectionSourceId(null)
      }

      if (
        (event.key === "Backspace" || event.key === "Delete") &&
        selectedNodeId
      ) {
        deleteSelectedNode()
      }
    }

    window.addEventListener("keydown", handleKey)
    return () => window.removeEventListener("keydown", handleKey)
  }, [deleteSelectedNode, selectedNodeId])

  const addNode = useCallback(
    (
      label = "Untitled service",
      kind: DraftNodeKind = "service",
      tone: DraftTone = "neutral"
    ) => {
      const id = `node-${crypto.randomUUID()}`
      const selectedPosition = selectedNode?.position ?? { x: 480, y: 288 }
      const nextNode: DraftNode = {
        id,
        type: "node",
        position: {
          x: selectedPosition.x,
          y:
            selectedPosition.y +
            DRAFT_NODE_HEIGHT +
            DRAFT_GRID_SIZE * 4,
        },
        size: { width: DRAFT_NODE_WIDTH, height: DRAFT_NODE_HEIGHT },
        data: {
          label,
          eyebrow: kind.toUpperCase(),
          detail: "new diagram node",
          status: "DRAFT",
          tone,
          kind,
        },
      }

      setDiagramDocument((current) =>
        normalizeDraftDocument({
          ...current,
          graph: {
            nodes: [...current.graph.nodes, nextNode],
            edges: selectedNode
              ? [
                  ...current.graph.edges,
                  {
                    id: `edge-${selectedNode.id}-${id}`,
                    source: selectedNode.id,
                    target: id,
                    sourcePort: "bottom",
                    targetPort: "top",
                    tone,
                  },
                ]
              : current.graph.edges,
          },
        })
      )
      setSelectedNodeId(id)
      setActiveTool("select")
      return id
    },
    [selectedNode]
  )

  const handleTool = (tool: ToolId) => {
    setConnectionSourceId(null)
    if (tool === "node") {
      addNode()
      return
    }
    if (tool === "text") {
      addNode("Annotation", "note", "violet")
      return
    }
    setActiveTool(tool)
  }

  const patchSelectedNode = (patch: Partial<DraftNodeData>) => {
    if (!selectedNodeId) return
    setDiagramDocument((current) => ({
      ...current,
      graph: {
        ...current.graph,
        nodes: current.graph.nodes.map((node) =>
          node.id === selectedNodeId && node.type === "node"
            ? { ...node, data: { ...node.data, ...patch } }
            : node
        ),
      },
    }))
  }

  const moveNode = (nodeId: string, position: DraftPoint) => {
    setDiagramDocument((current) => ({
      ...current,
      graph: {
        ...current.graph,
        nodes: current.graph.nodes.map((node) => {
          if (node.id !== nodeId || node.type !== "node") return node

          return {
            ...node,
            position: {
              x: snapToDraftGrid(
                Math.min(
                  Math.max(position.x, 0),
                  current.canvas.width - node.size.width
                )
              ),
              y: snapToDraftGrid(
                Math.min(
                  Math.max(position.y, 0),
                  current.canvas.height - node.size.height
                )
              ),
            },
          }
        }),
      },
    }))
  }

  const connectNode = (nodeId: string) => {
    if (!connectionSourceId) {
      setConnectionSourceId(nodeId)
      showNotice("Select a target node")
      return
    }
    if (connectionSourceId === nodeId) return

    setDiagramDocument((current) => ({
      ...current,
      graph: {
        ...current.graph,
        edges: [
          ...current.graph.edges,
          {
            id: `edge-${crypto.randomUUID()}`,
            source: connectionSourceId,
            target: nodeId,
            sourcePort: "bottom",
            targetPort: "top",
            tone: "neutral",
          },
        ],
      },
    }))
    setConnectionSourceId(null)
    setActiveTool("select")
    showNotice("Nodes connected")
  }

  const resetDiagram = () => {
    const next = createInitialDocument()
    setDiagramDocument(next)
    setViewport({
      x: 0,
      y: 0,
      width: next.canvas.width,
      height: next.canvas.height,
    })
    setSelectedNodeId("edge-proxy")
    setConnectionSourceId(null)
    showNotice("Diagram reset")
  }

  const exportDocument = () => {
    const prepared = prepareDraftDocument(diagramDocument)
    const blob = new Blob([JSON.stringify(prepared, null, 2)], {
      type: "application/json",
    })
    const url = URL.createObjectURL(blob)
    const link = window.document.createElement("a")
    link.href = url
    link.download = `${prepared.meta.id}.draft.json`
    link.click()
    URL.revokeObjectURL(url)
    showNotice("Draft file exported")
  }

  const copyDocument = async () => {
    await navigator.clipboard.writeText(
      JSON.stringify(prepareDraftDocument(diagramDocument), null, 2)
    )
    showNotice("Diagram JSON copied")
  }

  const runCommand = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const value = command.trim()
    if (!value) return

    const lower = value.toLowerCase()
    const kind: DraftNodeKind =
      lower.includes("database") || lower.includes("store")
        ? "database"
        : lower.includes("queue") || lower.includes("stream")
          ? "queue"
          : lower.includes("gateway") || lower.includes("proxy")
            ? "gateway"
            : "service"
    const tone: DraftTone =
      kind === "database"
        ? "green"
        : kind === "queue"
          ? "red"
          : kind === "gateway"
            ? "blue"
            : "neutral"
    const label =
      value
        .replace(/^add\s+(an?\s+)?/i, "")
        .replace(/\s+(after|before|to)\s+.+$/i, "")
        .trim()
        .slice(0, 36) || "New service"

    addNode(label.charAt(0).toUpperCase() + label.slice(1), kind, tone)
    setCommand("")
    showNotice("Command applied locally")
  }

  const zoom = (factor: number) => {
    setViewport((current) => {
      const width = Math.min(
        diagramDocument.canvas.width * 2,
        Math.max(diagramDocument.canvas.width / 3, current.width * factor)
      )
      const height =
        width *
        (diagramDocument.canvas.height / diagramDocument.canvas.width)

      return {
        x: current.x + (current.width - width) / 2,
        y: current.y + (current.height - height) / 2,
        width,
        height,
      }
    })
  }

  const fitViewport = () => {
    setViewport({
      x: 0,
      y: 0,
      width: diagramDocument.canvas.width,
      height: diagramDocument.canvas.height,
    })
  }

  const selectedData = selectedNode?.data

  return (
    <DiagramProvider document={diagramDocument}>
      <main
        className={cn(styles.studio, presenting && styles.studioPresenting)}
      >
        <header className={styles.topbar}>
          <div className={styles.brand}>
            <span className={styles.brandMark} aria-hidden="true">
              D
            </span>
            <span className={styles.wordmark}>draft</span>
          </div>
          <Separator orientation="vertical" className={styles.headerSeparator} />
          <div className={styles.documentTitle}>
            <span>JONNY / DIAGRAMS</span>
            <strong>{diagramDocument.meta.title}</strong>
          </div>
          <div className={styles.topbarCenter}>
            <Badge variant="outline" className={styles.modeBadge}>
              <CircleDot aria-hidden="true" />
              VECTOR
            </Badge>
            <span className={styles.savedState}>
              <Check aria-hidden="true" />
              SAVED LOCALLY
            </span>
          </div>
          <div className={styles.topbarActions}>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className={styles.headerButton}
              onClick={() => setPresenting((current) => !current)}
            >
              {presenting ? <X /> : <Maximize2 />}
              {presenting ? "Exit" : "Present"}
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              className={styles.headerIconButton}
              aria-label="Share diagram"
              onClick={() => showNotice("Share links are next")}
            >
              <Share2 aria-hidden="true" />
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className={styles.exportButton}
                >
                  Export
                  <ChevronDown aria-hidden="true" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className={styles.exportMenu}>
                <DropdownMenuLabel>Draft document</DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={exportDocument}>
                  <Download />
                  Download .draft.json
                </DropdownMenuItem>
                <DropdownMenuItem onClick={copyDocument}>
                  <Copy />
                  Copy diagram JSON
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={resetDiagram}>
                  <RotateCcw />
                  Reset sample
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </header>

        <aside className={styles.toolRail} aria-label="Diagram tools">
          <div className={styles.toolRailTop}>
            {toolItems.map((item, index) => (
              <div key={item.id}>
                {index === 2 ? (
                  <Separator className={styles.toolSeparator} />
                ) : null}
                <ToolButton
                  item={item}
                  active={activeTool === item.id}
                  onClick={() => handleTool(item.id)}
                />
              </div>
            ))}
          </div>
          <div className={styles.toolRailBottom}>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={styles.toolButton}
                  aria-label="Add frame"
                  onClick={() => showNotice("Frames are part of the next pass")}
                >
                  <Frame aria-hidden="true" />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="right" sideOffset={8}>
                Add frame
              </TooltipContent>
            </Tooltip>
          </div>
        </aside>

        <section className={styles.canvas} aria-label="Diagram canvas">
          <div className={styles.canvasMeta}>
            <span>REQUEST PATH / V.01</span>
            <span>{nodes.filter((node) => node.type === "node").length} NODES</span>
            <span>{edges.length} EDGES</span>
          </div>

          <DiagramFrame className={styles.editorFrame}>
            <Diagram viewport={viewport}>
              {!presenting ? (
                <DiagramEditorOverlay
                  document={diagramDocument}
                  activeTool={activeTool}
                  selectedNodeId={selectedNodeId}
                  connectionSourceId={connectionSourceId}
                  viewport={viewport}
                  onSelectNode={setSelectedNodeId}
                  onMoveNode={moveNode}
                  onConnectNode={connectNode}
                  onChangeViewport={setViewport}
                />
              ) : null}
            </Diagram>
          </DiagramFrame>

          <div className={styles.canvasControls} aria-label="Canvas view">
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Zoom out"
              onClick={() => zoom(1.2)}
            >
              <Minus />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Fit diagram"
              onClick={fitViewport}
            >
              <Scan />
            </Button>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label="Zoom in"
              onClick={() => zoom(0.8)}
            >
              <Plus />
            </Button>
          </div>

          <DiagramFrame className={styles.miniMap}>
            <Diagram />
          </DiagramFrame>

          <form className={styles.commandBar} onSubmit={runCommand}>
            <span className={styles.commandIcon}>
              <Sparkles aria-hidden="true" />
            </span>
            <label className="sr-only" htmlFor="draft-command">
              Describe a diagram change
            </label>
            <input
              id="draft-command"
              value={command}
              onChange={(event) => setCommand(event.target.value)}
              placeholder="Describe a change…"
              autoComplete="off"
            />
            <span className={styles.commandHint}>LOCAL COMMAND</span>
            <Button
              type="submit"
              variant="ghost"
              size="icon-sm"
              className={styles.commandSubmit}
              aria-label="Apply command"
              disabled={!command.trim()}
            >
              <ArrowDownToLine aria-hidden="true" />
            </Button>
          </form>

          <div className={styles.canvasFooter}>
            <span>SIN1</span>
            <span className={styles.footerPulse} />
            <span>LIVE DOCUMENT</span>
            <span className={styles.footerDivider} />
            <span>GRID {DRAFT_GRID_SIZE}PX</span>
            <span>SNAP ON</span>
          </div>
        </section>

        <aside className={styles.inspector} aria-label="Inspector">
          <div className={styles.inspectorHeader}>
            <div>
              <span>INSPECTOR</span>
              <strong>{selectedData?.label ?? "No selection"}</strong>
            </div>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              className={styles.inspectorClose}
              aria-label="Clear selection"
              onClick={() => setSelectedNodeId(null)}
              disabled={!selectedNode}
            >
              <X aria-hidden="true" />
            </Button>
          </div>

          {selectedNode && selectedData ? (
            <div className={styles.inspectorContent}>
              <section className={styles.inspectorSection}>
                <div className={styles.sectionTitle}>
                  <span>CONTENT</span>
                  <span>01</span>
                </div>
                <label className={styles.field}>
                  <span>LABEL</span>
                  <Input
                    value={selectedData.label}
                    onChange={(event) =>
                      patchSelectedNode({ label: event.target.value })
                    }
                  />
                </label>
                <label className={styles.field}>
                  <span>DETAIL</span>
                  <Input
                    value={selectedData.detail ?? ""}
                    onChange={(event) =>
                      patchSelectedNode({ detail: event.target.value })
                    }
                  />
                </label>
                <label className={styles.field}>
                  <span>STATUS</span>
                  <Input
                    value={selectedData.status ?? ""}
                    onChange={(event) =>
                      patchSelectedNode({ status: event.target.value })
                    }
                  />
                </label>
              </section>

              <Separator className={styles.inspectorSeparator} />

              <section className={styles.inspectorSection}>
                <div className={styles.sectionTitle}>
                  <span>SIGNAL</span>
                  <span>02</span>
                </div>
                <ToggleGroup
                  type="single"
                  value={selectedData.tone}
                  onValueChange={(value) => {
                    if (value) patchSelectedNode({ tone: value as DraftTone })
                  }}
                  className={styles.toneGroup}
                  aria-label="Node signal colour"
                >
                  {(Object.keys(DRAFT_TONE_COLORS) as DraftTone[]).map(
                    (tone) => (
                      <ToggleGroupItem
                        key={tone}
                        value={tone}
                        aria-label={tone}
                        className={styles.toneButton}
                        style={
                          {
                            "--tone-color": DRAFT_TONE_COLORS[tone],
                          } as CSSProperties
                        }
                      >
                        <span />
                      </ToggleGroupItem>
                    )
                  )}
                </ToggleGroup>
              </section>

              <Separator className={styles.inspectorSeparator} />

              <section className={styles.inspectorSection}>
                <div className={styles.sectionTitle}>
                  <span>POSITION</span>
                  <span>03</span>
                </div>
                <div className={styles.coordinates}>
                  <span>
                    X
                    <strong>{selectedNode.position.x}</strong>
                  </span>
                  <span>
                    Y
                    <strong>{selectedNode.position.y}</strong>
                  </span>
                </div>
              </section>

              <div className={styles.inspectorActions}>
                <Button
                  type="button"
                  variant="destructive"
                  size="sm"
                  onClick={deleteSelectedNode}
                >
                  <Trash2 aria-hidden="true" />
                  Delete node
                </Button>
              </div>
            </div>
          ) : (
            <div className={styles.emptyInspector}>
              <Network aria-hidden="true" />
              <strong>Select a node</strong>
              <span>Inspect its content, signal, and position.</span>
            </div>
          )}

          <div className={styles.inspectorHistory}>
            <span>HISTORY</span>
            <div>
              <Button
                type="button"
                variant="ghost"
                size="icon-sm"
                aria-label="Undo"
                disabled
              >
                <Undo2 aria-hidden="true" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon-sm"
                aria-label="Redo"
                disabled
              >
                <Redo2 aria-hidden="true" />
              </Button>
            </div>
          </div>
        </aside>

        {notice ? (
          <div className={styles.notice} role="status">
            <Check aria-hidden="true" />
            {notice}
          </div>
        ) : null}
      </main>
    </DiagramProvider>
  )
}

.studio {
  --chrome: #0a0a0a;
  --chrome-raised: #0f0f0f;
  --canvas: #070707;
  --line: #242424;
  --line-strong: #343434;
  --text: #e2e2e2;
  --muted: #747474;
  --faint: #474747;
  position: fixed;
  inset: 0;
  display: grid;
  grid-template:
    "header header header" 48px
    "tools canvas inspector" minmax(0, 1fr) / 48px minmax(0, 1fr) 276px;
  overflow: hidden;
  background: var(--canvas);
  color: var(--text);
  font-family: var(--font-geist-sans);
}

.topbar {
  grid-area: header;
  display: grid;
  grid-template-columns: auto 1px minmax(200px, 1fr) auto minmax(200px, 1fr);
  align-items: center;
  min-width: 0;
  border-bottom: 1px solid var(--line);
  background: var(--chrome);
  z-index: 30;
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 14px;
}

.brandMark {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 1px solid #d8d8d8;
  color: #e9e9e9;
  font-family: var(--font-geist-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.wordmark {
  font-family: var(--font-geist-mono);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.headerSeparator {
  height: 22px;
  background: var(--line);
}

.documentTitle {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  white-space: nowrap;
}

.documentTitle span,
.savedState,
.canvasMeta,
.canvasFooter,
.modeBadge,
.commandHint {
  font-family: var(--font-geist-mono);
  font-size: 9px;
  font-weight: 560;
  letter-spacing: 0.08em;
}

.documentTitle span {
  color: var(--faint);
}

.documentTitle strong {
  overflow: hidden;
  color: #bcbcbc;
  font-size: 11px;
  font-weight: 500;
  text-overflow: ellipsis;
}

.topbarCenter {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
}

.modeBadge {
  height: 20px;
  border-color: var(--line);
  border-radius: 3px;
  background: #0d0d0d;
  color: #848484;
}

.modeBadge svg {
  width: 9px;
  color: #61b995;
}

.savedState {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #5d5d5d;
}

.savedState svg {
  width: 11px;
  height: 11px;
  color: #61b995;
}

.topbarActions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  padding: 0 8px;
}

.headerButton,
.headerIconButton {
  border-radius: 3px;
  color: #858585;
  font-family: var(--font-geist-mono);
  font-size: 9px;
  letter-spacing: 0.05em;
}

.headerButton:hover,
.headerIconButton:hover {
  background: #151515;
  color: #d2d2d2;
}

.exportButton {
  height: 28px;
  margin-left: 3px;
  border-color: #333;
  border-radius: 3px;
  background: #141414;
  color: #c8c8c8;
  font-family: var(--font-geist-mono);
  font-size: 9px;
  letter-spacing: 0.05em;
}

.exportButton:hover {
  background: #1b1b1b;
}

.exportMenu {
  min-width: 210px;
  border-color: #2d2d2d;
  border-radius: 4px;
  background: #111;
  color: #c8c8c8;
}

.toolRail {
  grid-area: tools;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px solid var(--line);
  background: var(--chrome);
  z-index: 20;
}

.toolRailTop,
.toolRailBottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 5px;
}

.toolRailBottom {
  border-top: 1px solid var(--line);
}

.toolButton {
  width: 34px;
  height: 34px;
  border: 1px solid transparent;
  border-radius: 3px;
  color: #616161;
}

.toolButton:hover {
  background: #141414;
  color: #bdbdbd;
}

.toolButtonActive {
  border-color: #333;
  background: #171717;
  color: #e4e4e4;
}

.toolButton svg {
  width: 15px;
  height: 15px;
  stroke-width: 1.5;
}

.toolSeparator {
  width: 28px;
  margin: 6px 0;
  background: var(--line);
}

.canvas {
  grid-area: canvas;
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--canvas);
}

.canvas::before {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.012), transparent 18%),
    radial-gradient(circle at 50% 45%, rgba(255, 255, 255, 0.018), transparent 45%);
  content: "";
  pointer-events: none;
}

.editorFrame {
  position: absolute;
  inset: 0;
  border: 0;
}

.selectionBox {
  fill: none;
  stroke: #8a8a8a;
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.selectionPort {
  fill: #0b0b0b;
  stroke: #8a8a8a;
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.nodeHitArea {
  cursor: grab;
  outline: none;
}

.nodeHitArea:active {
  cursor: grabbing;
}

.nodeConnectArea {
  cursor: crosshair;
}

.connectionSource {
  stroke: #a97ad5;
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.pannablePane {
  cursor: grab;
}

.pannablePane:active {
  cursor: grabbing;
}

.canvasMeta {
  position: absolute;
  top: 12px;
  left: 14px;
  z-index: 15;
  display: flex;
  align-items: center;
  gap: 14px;
  color: #505050;
  pointer-events: none;
}

.canvasMeta span + span::before {
  margin-right: 14px;
  color: #2d2d2d;
  content: "/";
}

.canvasControls {
  position: absolute;
  bottom: 35px;
  left: 12px;
  z-index: 17;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid #292929;
  border-radius: 3px;
  background: #0c0c0c;
}

.canvasControls button {
  border-radius: 0;
  color: #606060;
}

.canvasControls button + button {
  border-top: 1px solid #292929;
}

.canvasControls button:hover {
  background: #171717;
  color: #b8b8b8;
}

.miniMap {
  position: absolute;
  right: 12px;
  bottom: 35px;
  z-index: 17;
  width: 126px;
  height: 82px;
  overflow: hidden;
  border: 1px solid #292929;
  border-radius: 3px;
  background: #090909;
  pointer-events: none;
}

.commandBar {
  position: absolute;
  bottom: 45px;
  left: 50%;
  z-index: 18;
  display: grid;
  grid-template-columns: 30px minmax(150px, 440px) auto 30px;
  width: min(620px, calc(100% - 220px));
  height: 40px;
  align-items: center;
  border: 1px solid #303030;
  border-radius: 4px;
  background: rgba(13, 13, 13, 0.96);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.35);
  transform: translateX(-50%);
}

.commandIcon {
  display: grid;
  height: 100%;
  place-items: center;
  border-right: 1px solid #252525;
  color: #a97ad5;
}

.commandIcon svg {
  width: 13px;
}

.commandBar input {
  min-width: 0;
  height: 100%;
  padding: 0 12px;
  border: 0;
  outline: 0;
  background: transparent;
  color: #c7c7c7;
  font-family: var(--font-geist-sans);
  font-size: 12px;
}

.commandBar input::placeholder {
  color: #4d4d4d;
}

.commandHint {
  padding: 3px 7px;
  border: 1px solid #252525;
  border-radius: 2px;
  color: #424242;
  white-space: nowrap;
}

.commandSubmit {
  width: 26px;
  height: 26px;
  border-radius: 2px;
  color: #636363;
}

.commandSubmit:not(:disabled):hover {
  background: #1a1a1a;
  color: #d0d0d0;
}

.canvasFooter {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 16;
  display: flex;
  height: 24px;
  align-items: center;
  gap: 9px;
  padding: 0 10px;
  border-top: 1px solid #1d1d1d;
  background: rgba(8, 8, 8, 0.94);
  color: #3f3f3f;
}

.footerPulse {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #61b995;
  box-shadow: 0 0 7px rgba(97, 185, 149, 0.55);
}

.footerDivider {
  width: 1px;
  height: 10px;
  margin: 0 3px;
  background: #242424;
}

.inspector {
  grid-area: inspector;
  position: relative;
  display: flex;
  min-height: 0;
  flex-direction: column;
  border-left: 1px solid var(--line);
  background: var(--chrome);
  z-index: 20;
}

.inspectorHeader {
  display: flex;
  min-height: 62px;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px 0 14px;
  border-bottom: 1px solid var(--line);
}

.inspectorHeader > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 5px;
}

.inspectorHeader span,
.sectionTitle,
.field > span,
.inspectorHistory > span {
  color: #4e4e4e;
  font-family: var(--font-geist-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.09em;
}

.inspectorHeader strong {
  overflow: hidden;
  color: #bcbcbc;
  font-size: 11px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inspectorClose {
  border-radius: 2px;
  color: #4d4d4d;
}

.inspectorContent {
  min-height: 0;
  overflow-y: auto;
}

.inspectorSection {
  display: flex;
  flex-direction: column;
  gap: 11px;
  padding: 14px;
}

.sectionTitle {
  display: flex;
  justify-content: space-between;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field input {
  height: 30px;
  border-color: #2a2a2a;
  border-radius: 3px;
  background: #0d0d0d;
  color: #b8b8b8;
  font-size: 11px;
  box-shadow: none;
}

.field input:focus-visible {
  border-color: #4b4b4b;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.035);
}

.inspectorSeparator {
  background: var(--line);
}

.toneGroup {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
}

.toneButton {
  height: 28px;
  padding: 0;
  border: 1px solid #292929;
  border-radius: 3px;
  background: #0c0c0c;
}

.toneButton:hover,
.toneButton[data-state="on"] {
  border-color: #4b4b4b;
  background: #171717;
}

.toneButton span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--tone-color);
  box-shadow: 0 0 8px color-mix(in srgb, var(--tone-color), transparent 55%);
}

.coordinates {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.coordinates > span {
  display: flex;
  height: 30px;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px;
  border: 1px solid #292929;
  border-radius: 3px;
  background: #0c0c0c;
  color: #4c4c4c;
  font-family: var(--font-geist-mono);
  font-size: 8px;
}

.coordinates strong {
  color: #888;
  font-weight: 500;
}

.inspectorActions {
  padding: 4px 14px 16px;
}

.inspectorActions button {
  width: 100%;
  border-radius: 3px;
  font-family: var(--font-geist-mono);
  font-size: 9px;
}

.emptyInspector {
  display: flex;
  min-height: 220px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  padding: 24px;
  color: #3f3f3f;
  text-align: center;
}

.emptyInspector svg {
  width: 20px;
  height: 20px;
  margin-bottom: 5px;
  stroke-width: 1;
}

.emptyInspector strong {
  color: #777;
  font-size: 11px;
  font-weight: 500;
}

.emptyInspector span {
  max-width: 160px;
  font-size: 10px;
  line-height: 1.5;
}

.inspectorHistory {
  display: flex;
  min-height: 40px;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding: 0 8px 0 14px;
  border-top: 1px solid var(--line);
}

.inspectorHistory > div {
  display: flex;
}

.notice {
  position: fixed;
  right: 292px;
  bottom: 38px;
  z-index: 60;
  display: flex;
  height: 30px;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid #343434;
  border-radius: 3px;
  background: #151515;
  color: #a9a9a9;
  font-family: var(--font-geist-mono);
  font-size: 9px;
  letter-spacing: 0.04em;
  animation: notice-in 160ms ease-out;
}

.notice svg {
  width: 11px;
  color: #61b995;
}

.studioPresenting {
  grid-template:
    "header header" 48px
    "canvas canvas" minmax(0, 1fr) / minmax(0, 1fr);
}

.studioPresenting .toolRail,
.studioPresenting .inspector,
.studioPresenting .commandBar,
.studioPresenting .canvasControls,
.studioPresenting .miniMap {
  display: none;
}

.studioPresenting .topbar {
  grid-template-columns: auto 1px minmax(200px, 1fr) auto minmax(200px, 1fr);
}

@keyframes notice-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 1040px) {
  .studio {
    grid-template:
      "header header" 48px
      "tools canvas" minmax(0, 1fr) / 48px minmax(0, 1fr);
  }

  .inspector {
    display: none;
  }

  .topbar {
    grid-template-columns: auto 1px minmax(140px, 1fr) auto;
  }

  .topbarCenter {
    display: none;
  }

  .notice {
    right: 12px;
  }
}

@media (max-width: 720px) {
  .studio {
    grid-template:
      "header" 44px
      "canvas" minmax(0, 1fr) / minmax(0, 1fr);
  }

  .topbar {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .headerSeparator,
  .toolRail,
  .documentTitle span,
  .headerButton,
  .headerIconButton,
  .canvasMeta,
  .miniMap {
    display: none;
  }

  .documentTitle {
    padding: 0 6px;
  }

  .topbarActions {
    padding-right: 6px;
  }

  .commandBar {
    bottom: 38px;
    grid-template-columns: 30px minmax(100px, 1fr) 30px;
    width: calc(100% - 24px);
  }

  .commandHint {
    display: none;
  }

  .canvasFooter span:nth-last-child(-n + 3) {
    display: none;
  }

  .canvasControls {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .notice {
    animation: none;
    transition: none;
  }
}
